// Digi's Building Tweaks: Build Restrictions, Station Extension Range, No Weather Damage, Repair Nearby, Wood Swap, Build Materials, Schematics, Stability Meter, Chest Snapping, Rug Lift, Level Strength.
// One plugin and one settings file for all of them: F1 shows a switch per sub-mod at the top, then each sub-mod's
// settings under its name. Generated by make_combined.py; the sub-mods' code is in Modules/.
using BepInEx;
using DigiCore;

namespace DigiBuilding
{
    [BepInPlugin(Guid, Name, Version)]
    [BepInDependency("com.jotunn.jotunn")]
    [BepInDependency("Searica.Valheim.TerrainTools", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("ValheimLegends", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("cdev.equipmentslots", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("com.alan.bettersmelter", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("ishid4.mods.betterarchery", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("randyknapp.mods.epicloot", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("sosal.nordicrugs", BepInDependency.DependencyFlags.SoftDependency)]
    [Jotunn.Utils.NetworkCompatibility(Jotunn.Utils.CompatibilityLevel.VersionCheckOnly, Jotunn.Utils.VersionStrictness.Minor)]
    public class Plugin : DigiPlugin
    {
        public const string Guid = "digi.valheim.building";
        public const string Name = "Digi's Building Tweaks";
        public const string Version = "1.0.33";

        protected override ModuleInfo[] Modules { get; } =
        {
            new ModuleInfo(typeof(global::BuildRestrictions.Plugin), "Build Restrictions", "digi.valheim.buildrestrictions", "Choose which building rules apply, set by the host for everyone.", new[] { "com.jotunn.jotunn" }, true),
            new ModuleInfo(typeof(global::StationRange.Plugin), "Station Range", "digi.valheim.stationrange", "A slider per crafting station for its build range (workbench, forge, stonecutter, ...); the default is the game's own range.", null, true),
            new ModuleInfo(typeof(global::ComfortRange.Plugin), "Comfort Range", "digi.valheim.comfortrange", "A slider per comfort group (fires, beds, banners, chairs, tables, rugs, ...) for how far away its pieces still count for comfort; 100% is the game's own 10 m.", null, true),
            new ModuleInfo(typeof(global::StationExtensionRange.Plugin), "Station Extension Range", "digi.valheim.stationextensionrange", "Station upgrades connect from further away and can stand next to each other.", null, true),
            new ModuleInfo(typeof(global::SnowUnderRoofs.Plugin), "Snow Under Roofs", "digi.valheim.snowunderroofs", "No snow on beams, floors and walls where a roof is above them (also where a roof passes through); a beam half outside keeps snow outside. On floors over deep snow: no snow clouds or wading slow.", null, true),
            new ModuleInfo(typeof(global::SnowToggle.Plugin), "Snow Toggle", "digi.valheim.snowtoggle", "Hide the snow on your roofs (or on every building piece) in the Deep North with one setting or key; only the look, switched back the snow is there as it was.", null, true),
            new ModuleInfo(typeof(global::NoWeatherDamage.Plugin), "No Weather Damage", "digi.valheim.noweatherdamage", "No rain damage on your buildings, and docks don't rot in water.", null, true),
            new ModuleInfo(typeof(global::RepairNearby.Plugin), "Repair Nearby", "digi.valheim.repairnearby", "Press Keypad + to repair every damaged building piece around you.", null, true),
            new ModuleInfo(typeof(global::WoodSwap.Plugin), "Wood Swap", "digi.valheim.roofswap", "Turn any wooden piece, or a whole building, into another wood (8 woods; thatch to shingles too), on the same snap points.", null, true, formerTitle: "Roof Swap"),
            new ModuleInfo(typeof(global::BuildMaterials.Plugin), "Build Materials", "digi.valheim.buildmaterials", "A hammer tool: click a building to see every material it costs, what you have (inventory and nearby chests) and what is missing.", null, true),
            new ModuleInfo(typeof(global::Schematics.Plugin), "Schematics", "digi.valheim.schematics", "A hammer tool: your saved schematics (from Ultimate Builder) with their pictures, and what each costs, what you have and what is missing.", null, true),
            new ModuleInfo(typeof(global::StabilityMeter.Plugin), "Stability Meter", "digi.valheim.stabilitymeter", "While the hammer is out, shows below the crosshair how stable the piece you aim at will end up, and warns when it will collapse.", null, false),
            new ModuleInfo(typeof(global::ChestSnapping.Plugin), "Chest Snapping", "digi.valheim.chestsnapping", "Chests, rugs, fermenters, furniture, machines and standing lights snap to their own kind and onto floor tiles (flush with a tile edge, centred; a 4x4 floor counts as four 2x2 tiles), hanging braziers under them, sconces and lanterns onto beams; Q / E pick the point.", null, true),
            new ModuleInfo(typeof(global::RugLift.Plugin), "Rug Lift", "digi.valheim.ruglift", "Nordic Rugs stop clipping into stone floors, can hang on walls and come in 2x and 3x sizes.", new[] { "com.jotunn.jotunn", "sosal.nordicrugs" }, true),
            new ModuleInfo(typeof(global::SafePortals.Plugin), "Safe Portals", "digi.valheim.safeportals", "Enemies stop going for your portals: in vanilla every portal is a priority target.", null, true),
            new ModuleInfo(typeof(global::SpawnFreeRange.Plugin), "Spawn-Free Range", "digi.valheim.spawnfreerange", "Workbenches, campfires and portals keep enemies from spawning twice as far away (a slider per kind).", null, true),
            new ModuleInfo(typeof(global::DismantleVehicles.Plugin), "Dismantle Vehicles", "digi.valheim.dismantlevehicles", "The hammer can take apart your ships, carts, battering ram and catapult: all materials back, cargo drops out.", null, true),
            new ModuleInfo(typeof(global::LevelStrength.Plugin), "Terrain Tools", "digi.valheim.levelstrength", "Hoe and cultivator tools: any size (Left Shift + mouse wheel), square mode (G), a steady outline of exactly what changes, new Smooth, Slope, Raise, Lower and Reset pieces, Level ground that flattens the whole area, and more than 8 m of height.", new[] { "com.jotunn.jotunn" }, true, formerTitle: "Level Strength"),
            new ModuleInfo(typeof(global::QuickRotate.Plugin), "Quick Rotate", "digi.valheim.quickrotate", "R turns the piece you are placing by 90 degrees (45 or 180 in the settings), Shift + R the other way.", null, true),
            new ModuleInfo(typeof(global::BuildMenuMemory.Plugin), "Build Menu Memory", "digi.valheim.buildmenumemory", "The build menu remembers the open folder of every tab (your own Favorites folders too) and the last tab of every tool, also after a restart.", null, true),
            new ModuleInfo(typeof(global::BeamFit.Plugin), "Beam Fit", "digi.valheim.beamfit", "Ashwood beams set into a Grausten wall show evenly on both sides of it, instead of half hidden or flickering.", null, true),
            new ModuleInfo(typeof(global::BuildCamera.Plugin), "Build Camera", "digi.valheim.buildcamera", "With the hammer, hoe or cultivator at a workbench, H lets the camera fly free to build from anywhere around it; flashlight, mist clearing and pickup included.", null, true),
        };
    }
}
